command:
/**
 * START A SYNCHRONIZED PRESENTATION
 *
 * Every world user observes the same terminal. The assigned controller
 * navigates freely; the GM does not approve each action.
 *
 * TERMINAL_UUID: UUID of the Terminal Journal to present.
 * CONTROLLER: exact name or ID of a connected user. An empty string uses
 * the GM who executes the macro.
 *
 * Important: every user must have Observer permission on the Journal and
 * must be able to see its Home page.
 */

// ── CONFIGURATION TO EDIT ─────────────────────────────────────
const TERMINAL_UUID = "JournalEntry.REPLACE_ME";
const CONTROLLER = ""; // Example: "Alice" or "abc123UserId"
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("This macro is for the GM only.");
const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal is not active.");
if (!TERMINAL_UUID || TERMINAL_UUID.includes("REPLACE_ME")) {
  return ui.notifications.warn("Edit TERMINAL_UUID in the macro configuration.");
}

const controller = CONTROLLER
  ? game.users.get(CONTROLLER) ?? game.users.find(user => user.name === CONTROLLER)
  : game.user;
if (!controller) return ui.notifications.error(`User not found: ${CONTROLLER}`);
if (!controller.active) return ui.notifications.error(`${controller.name} is not connected.`);

await api.shared.start({
  terminalRootUuid: TERMINAL_UUID,
  controllerUserId: controller.id
});
ui.notifications.info(`Presentation started — controller: ${controller.name}`);
